import { Property } from 'csstype';
import styled from 'styled-components';
import type { StyledComponent } from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import BoxShadows from '@dynatrace/strato-design-tokens/box-shadows';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Easings from '@dynatrace/strato-design-tokens/easings';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Timings from '@dynatrace/strato-design-tokens/timings';
import Typography from '@dynatrace/strato-design-tokens/typography';

import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';

type EditorContainerParameter = {
  $fullHeight: boolean;
  $hasError: boolean;
  $hideLineNumbers: boolean;
  $size?: 'default' | 'condensed';
  $focusStyle?: CSSFocusStylesObject;
  $readOnly?: boolean;
};

export const EditorContainer: StyledComponent<
  'div',
  object,
  EditorContainerParameter
> = /* @__PURE__ */ styled.div<EditorContainerParameter>(
  ({ $focusStyle }) => ({
    '> div': {
      position: 'relative',
      overflow: 'visible',
      '&::before': {
        content: "''",
        position: 'absolute',
        inset: '-2px',
        zIndex: 1,
        borderRadius: Borders.Radius.Container.Subdued,
        pointerEvents: 'none',
        ...$focusStyle,
      },
    },
  }),
  ({ $fullHeight }) =>
    $fullHeight && {
      display: 'flex',
      maxHeight: '100%',
      minHeight: '100%',
      flexGrow: 1,
      '.cm-editor': {
        width: '100%',
      },
    },
  ({ $hasError, $hideLineNumbers, $readOnly, $size }) => ({
    width: '100%',
    backgroundColor: Colors.Background.Container.Neutral.Subdued,

    '.cm-editor': {
      backgroundColor: Colors.Background.Surface.Default,
      borderRadius: Borders.Radius.Container.Subdued,
      borderWidth: Borders.Width.Emphasized,
      borderStyle: Borders.Style.Default,
      borderColor: $hasError
        ? Colors.Border.Critical.Default
        : Colors.Border.Neutral.Default,

      ...(!$readOnly && {
        '&:hover': {
          borderColor: $hasError
            ? Colors.Border.Critical.DefaultHover
            : Colors.Border.Neutral.DefaultHover,
        },
        '&:active': {
          borderColor: Colors.Border.Neutral.DefaultActive,
        },
      }),

      '&:focus-visible': {
        outline: 'none',
      },
    },

    '.cm-scroller': {
      // Match border radius (6px) with the editor container radius (8px)
      borderTopLeftRadius: `calc(${Borders.Radius.Container.Default}/2)`,
      borderBottomLeftRadius: `calc(${Borders.Radius.Container.Default}/2)`,
    },

    '.cm-scroller:focus-visible': {
      outline: 'none',
    },

    '.cm-highlight': {
      animation: `strato__editor__highlight__text ${Timings.Base.Default} ${Easings.OutBack},
      strato__editor__fade__out ${Timings.Slow.Gentle}`,
      animationDelay: `0s, ${Timings.Base.Default}`,
      animationIterationCount: 1,
      borderRadius: Spacings.Size2,
    },

    '.cm-content, .cm-gutters': {
      fontSize:
        $size !== 'default'
          ? Typography.Code.Small.Default.Size
          : Typography.Code.Base.Default.Size,
      fontFamily:
        $size !== 'default'
          ? Typography.Code.Small.Default.Family
          : Typography.Code.Base.Default.Family,
    },

    '.cm-gutters': {
      color: $hasError
        ? Colors.Text.Critical.Default
        : Colors.Text.Neutral.Subdued,
      backgroundColor: $hasError
        ? Colors.Background.Container.Critical.Emphasized
        : Colors.Background.Container.Neutral.Subdued,

      borderColor: $hasError
        ? Colors.Border.Critical.Default
        : Colors.Border.Neutral.Default,
      borderRightWidth: Borders.Width.Emphasized,
      borderRightStyle: Borders.Style.Default as Property.BorderRightStyle,
      textAlign: 'right',
    },

    '.cm-lineNumbers': {
      minWidth: $size !== 'default' ? '27px' : '33px',

      '& > .cm-gutterElement': {
        padding:
          $size !== 'default'
            ? `0 0 0 ${Spacings.Size12}`
            : `0 0 0 ${Spacings.Size16}`,
      },
    },

    '.cm-gutterElement': {
      color: Colors.Text.Neutral.Subdued,

      ...(!$readOnly &&
        !$hasError && {
          '&:hover': {
            color: Colors.Icon.Neutral.SubduedHover,
          },

          '&:active': {
            color: Colors.Text.Neutral.Default,
          },
        }),
    },

    '.cm-content': {
      color: Colors.Text.Neutral.Default,
      caretColor: Colors.Text.Neutral.Default,
      paddingBlock: $hideLineNumbers
        ? Spacings.Size2
        : $size !== 'default'
        ? Spacings.Size6
        : Spacings.Size12,
    },

    '.cm-placeholder': {
      color: Colors.Text.Neutral.Subdued,
    },

    '.cm-focused': {
      outline: '0 !important',
    },

    '.cm-line': {
      paddingInline: $size !== 'default' ? Spacings.Size12 : Spacings.Size16,
      lineHeight:
        $size !== 'default'
          ? Typography.Code.Small.Default.LineHeight
          : Typography.Code.Base.Default.LineHeight,
      color: $hasError
        ? Colors.Text.Critical.Default
        : Colors.Text.Neutral.Default,
    },

    ...(!$readOnly &&
      !$hideLineNumbers && {
        '.cm-activeLine': {
          outline: 'none',
          boxShadow: `0 calc(${Borders.Width.Default} * -1) 0 ${Colors.Border.Neutral.Default}, 0 ${Borders.Width.Default} 0 ${Colors.Border.Neutral.Default}`,
        },

        '.cm-activeLineGutter': {
          borderBlockColor: Colors.Border.Neutral.Default,
          color: $hasError
            ? Colors.Text.Critical.Default
            : Colors.Text.Neutral.Default,
        },
      }),

    '.cm-activeLine, .cm-activeLineGutter': {
      backgroundColor: 'transparent',
    },

    '.cm-tooltip': {
      background: Colors.Background.Surface.Default,
      color: Colors.Text.Neutral.Default,
      maxWidth: '500px',
      padding: Spacings.Size4,
      borderRadius: Borders.Radius.Surface.Subdued,
      boxShadow: BoxShadows.Surface.Floating.Rest,
      border: 'none',
    },

    '.cm-tooltip-below': {
      marginTop: Spacings.Size4,
    },

    '.tok-keyword, .tok-heading': {
      color: Colors.Syntax.Operators,
    },

    '.tok-string': {
      color: Colors.Syntax.String,
    },

    '.tok-number': {
      color: Colors.Syntax.Number,
    },

    '.tok-typeName': {
      color: Colors.Syntax.Classname,
    },

    '.tok-inserted, .tok-meta': {
      color: Colors.Text.Primary.Default,
    },

    '.tok-comment': {
      color: Colors.Syntax.Comment,
      fontStyle: 'italic',
    },

    '.tok-propertyName, .tok-variableName, .tok-link, .tok-atom': {
      color: Colors.Syntax.Variable,
    },

    '.tok-bool': {
      color: Colors.Syntax.Boolean,
    },

    '.cm-tooltip.cm-tooltip-autocomplete > ul > completion-section': {
      padding: `${Spacings.Size12} ${Spacings.Size12}  ${Spacings.Size4}`,
      border: 0,
      fontFamily: Typography.Text.Small.Emphasized.Family,
      color: Colors.Text.Neutral.Subdued,
      fontWeight: Typography.Text.Small.Emphasized.Weight,
      fontSize: Typography.Text.Small.Emphasized.Size,
      lineHeight: Typography.Text.Small.Emphasized.LineHeight,
      textDecoration: Typography.Text.Small.Emphasized.TextDecoration,
      textTransform: Typography.Text.Small.Emphasized
        .TextTransform as Property.TextTransform,
    },

    '.cm-tooltip-autocomplete > ul > li[role="option"]': {
      display: 'flex',
      flexWrap: 'wrap',
      justifyContent: 'flex-start',
      alignItems: 'center',
      gap: Spacings.Size4,
      padding: `${Spacings.Size6} ${Spacings.Size12}`,
    },

    '.cm-completionLabel': {
      fontSize:
        $size !== 'default'
          ? Typography.Code.Small.Default.Size
          : Typography.Code.Base.Default.Size,
      fontFamily:
        $size !== 'default'
          ? Typography.Code.Small.Default.Family
          : Typography.Code.Base.Default.Family,
      color: Colors.Text.Neutral.Default,
      fontWeight: Typography.Code.Base.Default.Weight,
      lineHeight: Typography.Code.Base.Default.LineHeight,
      textDecoration: Typography.Code.Base.Default.TextDecoration,
      textTransform: Typography.Code.Base.Default
        .TextTransform as Property.TextTransform,
      flexGrow: 3,
      overflow: 'hidden',
      textOverflow: 'ellipsis',
    },

    '.cm-tooltip-autocomplete': {
      width: '500px',
    },

    '.cm-tooltip.cm-tooltip-hover': {
      minWidth: 'auto',
    },

    '.cm-tooltip.cm-tooltip-autocomplete > ul': {
      maxHeight: '20em',
    },

    '.cm-tooltip.cm-tooltip-autocomplete > ul > li': {
      position: 'relative',
    },

    '.cm-tooltip.cm-tooltip-autocomplete > ul > li::after': {
      position: 'absolute',
      /* Required or else the outline would be cut off by the listbox boundaries */
      inset: Spacings.Size2,
      borderRadius: 'inherit',
      content: ' ',
    },

    '.cm-tooltip.cm-tooltip-autocomplete li': {
      borderRadius: Borders.Radius.Field.Default,

      '&[aria-selected]': {
        boxShadow: `inset 0 0 0 ${Borders.Width.Emphasized} ${Colors.Border.Neutral.Accent}, inset 0 0 0 calc(${Borders.Width.Emphasized} + 1px) ${Colors.Border.Neutral.Default}`,
        backgroundColor: 'transparent',
        '&:focus-visible': { outline: 'none' },
      },

      '&:hover': {
        backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
      },
    },

    // Provides the browser-based a11y outline (similar to menu)
    '.cm-tooltip.cm-tooltip-autocomplete > ul > li[aria-selected]::after, .cm-tooltip.cm-tooltip-autocomplete > ul > li:hover::after':
      {
        outline: 'currentColor auto medium',
      },

    '.cm-tooltip.cm-completionInfo': {
      padding: `calc(${Spacings.Size4} + ${Spacings.Size6}) ${Spacings.Size16}`,
      marginLeft: Spacings.Size4,
      marginRight: Spacings.Size4,
      maxWidth: '500px',
    },

    '.cm-tooltip-autocomplete > ul > li.cm-completionOption-action > div': {
      width: '100%',
    },

    '.cm-completionOption-action .cm-completionLabel': {
      display: 'none',
    },

    '.cm-diagnostics': {
      padding: `${Spacings.Size6} ${Spacings.Size12}`,
    },

    '.cm-diagnosticAction': {
      backgroundColor: 'transparent',
      borderRadius: 0,
      margin: 0,
      padding: 0,
    },

    '.cm-lintRange': {
      backgroundRepeat: 'repeat-x',
      backgroundSize: '8px 2px',
      backgroundPosition: '0 95%',
    },

    '.cm-lintPoint-error:after': {
      borderBottomColor: Colors.Text.Critical.Default,
    },

    '.cm-diagnostic-error': {
      borderLeft: `5px solid ${Colors.Text.Critical.Default}`,
    },

    '.cm-lintRange-error': {
      backgroundImage: `linear-gradient(
          45deg,
          transparent 65%,
          ${Colors.Text.Critical.Default} 80%,
          transparent 90%
        ),
        linear-gradient(
          135deg,
          transparent 5%,
          ${Colors.Text.Critical.Default} 15%,
          transparent 25%
        ),
        linear-gradient(
          135deg,
          transparent 45%,
          ${Colors.Text.Critical.Default} 55%,
          transparent 65%
        ),
        linear-gradient(
          45deg,
          transparent 25%,
          ${Colors.Text.Critical.Default} 35%,
          transparent 50%
        )`,
    },

    '.cm-lintPoint-warning:after': {
      borderBottomColor: `${Colors.Text.Warning.Default}`,
    },

    '.cm-diagnostic-warning': {
      borderLeft: `5px solid ${Colors.Text.Warning.Default}`,
    },

    '.cm-lintRange-warning': {
      backgroundImage: `linear-gradient(
          45deg,
          transparent 65%,
          ${Colors.Text.Warning.Default} 80%,
          transparent 90%
        ),
        linear-gradient(
          135deg,
          transparent 5%,
          ${Colors.Text.Warning.Default} 15%,
          transparent 25%
        ),
        linear-gradient(
          135deg,
          transparent 45%,
          ${Colors.Text.Warning.Default} 55%,
          transparent 65%
        ),
        linear-gradient(
          45deg,
          transparent 25%,
          ${Colors.Text.Warning.Default} 35%,
          transparent 50%
        )`,
    },

    '.cm-lintPoint-info:after': {
      borderBottomColor: `${Colors.Text.Neutral.Default}`,
    },

    '.cm-diagnostic-info': {
      borderLeft: `5px solid ${Colors.Text.Neutral.Default}`,
    },

    '.cm-lintRange-info': {
      backgroundImage: `linear-gradient(
          45deg,
          transparent 65%,
          ${Colors.Text.Neutral.Default} 80%,
          transparent 90%
        ),
        linear-gradient(
          135deg,
          transparent 5%,
          ${Colors.Text.Neutral.Default} 15%,
          transparent 25%
        ),
        linear-gradient(
          135deg,
          transparent 45%,
          ${Colors.Text.Neutral.Default} 55%,
          transparent 65%
        ),
        linear-gradient(
          45deg,
          transparent 25%,
          ${Colors.Text.Neutral.Default} 35%,
          transparent 50%
        )`,
    },

    '.cmt-keyword': {
      fontWeight: Typography.Text.Base.Emphasized.Weight as Property.FontWeight,
    },

    '@keyframes strato__editor__highlight__text': {
      to: {
        backgroundColor: Colors.Background.Container.Neutral.Accent,
        color: Colors.Text.OnAccent.Default,
      },
    },

    '@keyframes strato__editor__fade__out': {
      from: {
        backgroundColor: Colors.Background.Container.Neutral.Accent,
        color: Colors.Text.OnAccent.Default,
      },
    },
  }),
);

EditorContainer.displayName = 'EditorContainer';
